// Code «Elegir los fuera de plazo» (06 · Recordatorios y vencimientos) · Run Once for All Items
// Recibe la salida de «Leer apartados activos» ({ total, apartados }) y devuelve un item por apartado
// con fecha_limite anterior a hoy, o un solo item { id: null, hoy, activos } si no hay ninguno.

const busqueda = $input.first().json;
if (!Array.isArray(busqueda.apartados)) {
  throw new Error('Elegir los fuera de plazo: «Leer apartados activos» no ha devuelto { total, apartados }');
}
const activos = busqueda.total ?? busqueda.apartados.length;

// Hoy en la zona de la tienda, AAAA-MM-DD (la app también usa Europe/Madrid)
const hoy = DateTime.now().setZone('Europe/Madrid').toISODate();

// Fuera de plazo: fecha_limite anterior a hoy. El que vence hoy todavía admite abonos (la app daría 422).
// Las fechas AAAA-MM-DD se comparan como texto. No se recalcula nada
const fuera = busqueda.apartados
  .filter(a => a.estado === 'activo' && String(a.fecha_limite) < hoy)
  .sort((a, b) => String(a.fecha_limite).localeCompare(String(b.fecha_limite)) || a.id - b.id);

const salida = fuera.map(a => ({ json: { ...a, hoy, activos } }));

// Un Code nunca devuelve 0 items: el IF «¿Hay apartados que vencer?» va por false
return salida.length ? salida : [{ json: { id: null, hoy, activos } }];

// Code «Preparar lista» (06 · Recordatorios y vencimientos) · Run Once for All Items
// Empareja cada apartado de «Elegir los fuera de plazo» con su respuesta de «Vencer apartado» y devuelve
// { asunto, texto } para «Enviar lista a la tienda». Un 404 o un 422 van a la lista; otro código para el flujo.

const elegidos = $('Elegir los fuera de plazo').all().filter(i => i.json.id != null);
const respuestas = $input.all();

// Las respuestas llegan en el mismo orden que los apartados (Batching de 1)
if (respuestas.length !== elegidos.length) {
  throw new Error(`Vencer apartado: se esperaban ${elegidos.length} respuestas y llegaron ${respuestas.length}`);
}

// Mensaje de la app: {"detail": "..."} o, si falla la validación, {"detail": [{msg: ...}]}
function detalle(body) {
  let b = body;
  if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { return b; } }
  const d = b?.detail;
  if (Array.isArray(d)) return d.map(x => x.msg ?? JSON.stringify(x)).join('; ');
  return d ?? JSON.stringify(b);
}

const vencidos = [];
const fallidos = [];
const otros = [];
elegidos.forEach((item, i) => {
  const elegido = item.json;
  const r = respuestas[i].json;
  if (r.statusCode === 200) {
    let b = r.body;
    if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
    // El apartado y el vale son los de la app; el importe del vale no se calcula
    vencidos.push({ apartado: b?.apartado ?? elegido, vale: b?.vale ?? null });
  } else if (r.statusCode === 404 || r.statusCode === 422) {
    fallidos.push({ apartado: elegido, motivo: detalle(r.body) });
  } else {
    otros.push({ apartado: elegido, statusCode: r.statusCode, motivo: detalle(r.body) });
  }
});

const vale = v => (v ? v.codigo : '(sin vale)');

// 401, 5xx…: para el flujo y lo avisa el 08. Con Never Error se intentan todos, así que el mensaje
// lleva los que sí se vencieron: la siguiente ejecución ya no los verá (están vencido)
if (otros.length) {
  const [primero] = otros;
  const resto = otros.length > 1 ? ` (y en ${otros.length - 1} más: ${otros.slice(1).map(o => o.apartado.id).join(', ')})` : '';
  const ya = vencidos.length ? vencidos.map(v => `${v.apartado.id} (${vale(v.vale)})`).join(', ') : 'ninguno';
  throw new Error(`Vencer apartado: la app respondió ${primero.statusCode} en el apartado ${primero.apartado.id}: ${primero.motivo}${resto}. Ya vencidos: ${ya}`);
}

// ---------- Texto de la lista ----------

const dia = iso => String(iso).split('-').reverse().join('/');
const e = n => `${Number(n).toFixed(2)} €`;
const zapato = a => `${a.producto}${a.talla ? `, talla ${a.talla}` : ''}`;
const seccion = (titulo, lineas) => `${titulo} (${lineas.length})\n${lineas.length ? lineas.join('\n') : '- Ninguno'}\n`;

const { hoy, activos } = elegidos[0].json;
const n = vencidos.length;

const texto = [
  `Vencimientos del ${dia(hoy)}: ${n} ${n === 1 ? 'apartado vencido' : 'apartados vencidos'} de ${activos} activos revisados.`,
  '',
  seccion('ZAPATOS QUE VUELVEN A LA VENTA', vencidos.map(({ apartado: a, vale: v }) =>
    `- ${zapato(a)} · apartado ${a.id} · ${a.cliente} · plazo hasta el ${dia(a.fecha_limite)} · vale ${vale(v)}${v ? ` de ${e(v.importe)}` : ''}`)),
  seccion('NO SE HAN PODIDO VENCER', fallidos.map(({ apartado: a, motivo }) =>
    `- ${zapato(a)} · apartado ${a.id} · ${a.cliente}. La app respondió: «${motivo}»`)),
  'Los vales los ha generado la app con lo abonado en cada apartado. Cada cliente recibe su vale por correo; si no tiene email, llega un aviso aparte para avisarle por teléfono.',
].join('\n');

const asunto = `Vencimientos del ${dia(hoy)}: ${n} ${n === 1 ? 'par vuelve' : 'pares vuelven'} a la venta`
  + (fallidos.length ? ` · ${fallidos.length} con error` : '');

return [{ json: { asunto, texto } }];

// Elegir los que vencen pronto · Code · Run Once for All Items
const entrada = $input.first().json;
if (!Array.isArray(entrada.apartados) || !Number.isInteger(entrada.total) || entrada.total !== entrada.apartados.length) {
  throw new Error('Elegir los que vencen pronto: «Leer apartados activos» no ha devuelto { total, apartados }');
}
const partes = Object.fromEntries(new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Europe/Madrid', year: 'numeric', month: '2-digit', day: '2-digit',
}).formatToParts(new Date()).filter(p => p.type !== 'literal').map(p => [p.type, p.value]));
const hoy = `${partes.year}-${partes.month}-${partes.day}`;
const sumarDias = dias => {
  const fecha = new Date(`${hoy}T12:00:00Z`);
  fecha.setUTCDate(fecha.getUTCDate() + dias);
  return fecha.toISOString().slice(0, 10);
};
const objetivos = new Map([[sumarDias(7), 7], [sumarDias(1), 1]]);
const limpio = valor => valor == null ? '' : String(valor).trim();
const ids = new Set();
const salida = [];
for (const a of entrada.apartados) {
  if (a.estado !== 'activo') continue;
  if (typeof a.fecha_limite !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(a.fecha_limite) || !Number.isFinite(Date.parse(`${a.fecha_limite}T12:00:00Z`)) || new Date(`${a.fecha_limite}T12:00:00Z`).toISOString().slice(0,10) !== a.fecha_limite) {
    throw new Error('Elegir los que vencen pronto: fecha_limite no válida');
  }
  const dias = objetivos.get(a.fecha_limite);
  if (!dias) continue;
  if (!Number.isInteger(a.id) || a.id < 1 || ids.has(a.id)) throw new Error('Elegir los que vencen pronto: id no válido o duplicado');
  ids.add(a.id);
  if (typeof a.pendiente !== 'number' || !Number.isFinite(a.pendiente) || a.pendiente < 0) throw new Error('Elegir los que vencen pronto: pendiente no válido');
  if (!limpio(a.cliente) || !limpio(a.producto)) throw new Error('Elegir los que vencen pronto: falta cliente o producto');
  const email = limpio(a.email);
  const tiene_email = !!email;
  if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new Error('Elegir los que vencen pronto: email no válido');
  const fechaVisible = a.fecha_limite.split('-').reverse().join('/');
  const cuando = dias === 7 ? 'en 7 días' : 'mañana';
  const detalle = `Apartado n.º ${a.id}\nModelo: ${a.producto}\n${limpio(a.talla) ? `Talla: ${a.talla}\n` : ''}Pendiente: ${a.pendiente.toFixed(2)} €\nFecha límite: ${fechaVisible}`;
  const asunto = tiene_email ? `Tu apartado vence ${cuando}: ${a.producto}` : `Recordatorio sin email: ${a.cliente} · vence ${cuando}`;
  const texto = tiene_email
    ? `Hola ${a.cliente}:\n\nTu apartado vence ${cuando}.\n\n${detalle}\n\nPuedes completar el pago en la tienda o por Bizum/transferencia usando los datos habituales de la tienda. Indica el número de apartado en el concepto; si necesitas los datos de pago, contacta con la tienda.\n\nGracias,\nZapatería Paso Firme`
    : `Avisad por teléfono a ${a.cliente}: su apartado vence ${cuando} y no tiene email.\nTeléfono: ${limpio(a.telefono) || 'No consta; revisar la ficha del cliente'}\n\n${detalle}\n\nPuede completar el pago en la tienda o por Bizum/transferencia con los datos habituales, indicando el número de apartado.`;
  salida.push({ json: { id: a.id, apartado_id: a.id, dias, hoy, cliente: a.cliente, producto: a.producto, talla: a.talla ?? null, pendiente: a.pendiente, fecha_limite: a.fecha_limite, tiene_email, para: tiene_email ? email : 'tienda@pasofirme.example', asunto, texto }, pairedItem: { item: 0 } });
}
salida.sort((a,b) => a.json.fecha_limite.localeCompare(b.json.fecha_limite) || a.json.id-b.json.id);
return salida.length ? salida : [{ json: { id: null, hoy }, pairedItem: { item: 0 } }];

// Descartar avisos ya enviados · Code · Run Once for All Items
// Get lee TODO el histórico una sola vez; Always Output Data permite la tabla vacía.
const historico = $input.all().map(item => item.json);
const enviados = new Set();
for (const fila of historico) {
  if (Object.keys(fila).length === 0) continue;
  if (!Number.isInteger(fila.apartado_id) || fila.apartado_id < 1 || ![1,7].includes(fila.dias) || typeof fila.fecha !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(fila.fecha)) {
    throw new Error('Descartar avisos ya enviados: histórico no válido; revisar Recordatorios enviados');
  }
  enviados.add(`${fila.apartado_id}:${fila.dias}`);
}
const candidatos = $('Elegir los que vencen pronto').all();
const pendientes = candidatos.filter(item => item.json.id != null && !enviados.has(`${item.json.apartado_id}:${item.json.dias}`));
// Cada item de salida enlaza al histórico; los nodos posteriores recuperan SU item de este Code.
return pendientes.length
  ? pendientes.map(item => ({ json: { ...item.json }, pairedItem: { item: 0 } }))
  : [{ json: { id: null }, pairedItem: { item: 0 } }];

// Run once for each item. The model receives generic style instructions only.
const base = $json;
if (typeof base.texto !== 'string' || !base.texto || typeof base.para !== 'string') throw new Error('Falta el recordatorio original');
const prompt_ia = 'Redacta en español dos frases breves y cercanas para acompañar un recordatorio de Zapatería Paso Firme. Devuelve JSON con exactamente introduccion y despedida, ambas strings. Solo tono cordial; no incluyas datos personales, cifras, números escritos, importes, pagos, descuentos, fechas, plazos, enlaces ni instrucciones de negocio. No uses artículos un/una. No saludes a ninguna persona concreta. Ejemplo de estilo: Te escribimos con cariño para cuidar de tu apartado. / Nos encantará verte por la tienda. No añadas información ni promesas.';
return { json: { ...base, prompt_ia } };

// Run once for each item. Never replace or recompute any original financial detail.
const base = $('Preparar redacción del recordatorio').item.json;
const { prompt_ia, ...original } = base;
const fallback = () => ({ json: { ...original, redaccion_ia: 'plantilla' } });
const response = $json;
if (response.statusCode !== 200 || response.error) return fallback();
let content;
try {
  const body = typeof response.body === 'string' ? JSON.parse(response.body) : response.body;
  content = JSON.parse(body.choices[0].message.content);
} catch { return fallback(); }
if (!content || typeof content !== 'object' || Array.isArray(content) || Object.keys(content).sort().join(',') !== 'despedida,introduccion') return fallback();
const forbidden = /\b(?:un|una|uno|dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez|once|doce|trece|catorce|quince|dieci\w*|veint\w*|treinta|cuarenta|cincuenta|sesenta|setenta|ochenta|noventa|cien\w*|doscientos|trescientos|cuatrocientos|quinientos|seiscientos|setecientos|ochocientos|novecientos|mil\w*|billon\w*|cero|medio|media|mitad|doble|triple|primero|ultimo|importe|saldo|pendiente|plazo\w*|fecha\w*|vence\w*|vencim\w*|paga\w*|pago\w*|abono\w*|descuent\w*|gratis|gratuit\w*|cost\w*|euro\w*|centim\w*|dia\w*|manana|semana\w*|mes\w*|ano\w*|hoy|ayer|hora\w*|minuto\w*|dinero|porcentaje\w*)\b/iu;
const safe = value => {
  if (typeof value !== 'string' || value.length < 10 || value.length > 180 || /[^\p{L}\p{M} ,.!¡¿?;:()\-]/u.test(value)) return false;
  const normalized = value.normalize('NFD').replace(/\p{M}/gu, '').toLowerCase();
  return !forbidden.test(normalized);
};
if (!safe(content.introduccion) || !safe(content.despedida)) return fallback();
return { json: { ...original, texto: `${content.introduccion}\n\n${original.texto}\n\n${content.despedida}`, redaccion_ia: 'aceptada' } };
